        addSubjectQs(8, "Health Care Economics & Policy", "KMU ECO-683 / Feldstein Health Care Economics", eco)

        // ==========================================
        // 4. PROFESSIONAL ELECTIVE / DISASTER MANAGEMENT - 50 Qs
        // ==========================================
        val dis = listOf(
            Triple("Disaster defined by United Nations Office for Disaster Risk Reduction (UNDRR) is a serious disruption of community functioning causing widespread human, material, economic, or environmental losses exceeding the community's capacity to cope using its own:", listOf("Foreign debt", "Internal resources", "Police force", "Hospital beds"), 1),
            Triple("Disaster Management Cycle consists of four continuous phases: Prevention / Mitigation, Preparedness, Response, and:", listOf("Panic", "Recovery / Rehabilitation", "Investigation", "Demolition"), 1),
            Triple("Disaster Mitigation phase involves long-term measures designed to eliminate or reduce the impact and risks of hazards BEFORE a disaster occurs, exemplified by:", listOf("Distributing food during flood", "Building earthquake-resistant hospital infrastructure and flood levees", "Triage at disaster site", "Rebuilding homes post disaster"), 1),
            Triple("Disaster Preparedness phase activities include creating emergency response plans, conducting disaster drills, establishing warning systems, and:", listOf("Constructing dams", "Stockpiling emergency medical supplies and training response personnel", "Filing insurance claims", "Clearing rubble"), 1),
            Triple("Disaster Response phase occurs IMMEDIATELY during and post impact, focusing primarily on search and rescue, rapid medical triage, and providing:", listOf("Long-term economic loans", "Emergency life-saving medical care, shelter, and clean water", "Architectural redesign", "Academic research"), 1),
            Triple("Disaster Recovery / Rehabilitation phase focuses on restoring normal community functioning, rebuilding infrastructure, providing psychological counseling, and:", listOf("Conducting emergency triage", "Re-establishing sustainable healthcare systems and long-term socio-economic recovery", "Triggering evacuation alarms", "Executing START triage"), 1),
            Triple("Mass Casualty Incident (MCI) is defined as an emergency event where the number and severity of casualties overwhelms available local healthcare resources and:", listOf("Requires no extra help", "Demands extraordinary emergency response capabilities and triage protocol", "Affects only 1 person", "Causes zero injuries"), 1),
            Triple("START Triage algorithm used in mass casualty incidents stands for:", listOf("Systematic Treatment And Rapid Transport", "Simple Triage And Rapid Treatment", "Standard Triage And Rescue Technique", "Swift Treatment And Emergency Triage"), 1),
            Triple("Under START Triage algorithm, first step performed by triage nurse at mass casualty scene is shouting clear verbal instructions directing all casualties who can walk to move to a designated area. These walking wounded patients are assigned triage tag color:", listOf("Red (Immediate)", "Yellow (Delayed)", "Green (Minor / Walking Wounded)", "Black (Expectant / Deceased)"), 2),
            Triple("Under START Triage, an adult casualty who is NOT breathing initially has their airway manually opened (Head-Tilt/Chin-Lift). If breathing does NOT resume after opening airway, patient is tagged:", listOf("Red", "Yellow", "Green", "Black (Expectant / Deceased)"), 3),
            Triple("Under START Triage, if an un-breathing casualty STOPS and starts breathing post manual airway opening, they are immediately tagged:", listOf("Red (Immediate - priority 1)", "Yellow (Delayed)", "Green (Minor)", "Black"), 0),
            Triple("Under START Triage, a breathing casualty with Respiratory Rate > 30 breaths/minute is immediately assigned triage tag color:", listOf("Yellow", "Red (Immediate - priority 1)", "Green", "Black"), 1),
            Triple("Under START Triage, a breathing casualty with Respiratory Rate < 30/min, Capillary Refill > 2 seconds (or absent radial pulse) is tagged:", listOf("Yellow", "Red (Immediate - priority 1)", "Green", "Black"), 1),
            Triple("Under START Triage, a casualty who breathes < 30/min, has Capillary Refill < 2 sec / normal radial pulse, but CANNOT follow simple commands ('raise 2 fingers') is tagged:", listOf("Yellow", "Red (Immediate - priority 1)", "Green", "Black"), 1),
            Triple("Under START Triage, a casualty who breathes < 30/min, normal capillary refill, AND CAN follow simple commands is assigned triage tag color:", listOf("Red", "Yellow (Delayed - priority 2)", "Green", "Black"), 1),
            Triple("JumpSTART Triage algorithm is specifically modified for mass casualty triage of:", listOf("Elderly nursing home patients", "Pediatric patients under 8 years of age (including 5 rescue breaths for respiratory arrest)", "Pregnant women", "Chemical spill victims"), 1),
            Triple("Command and control organizational framework universally utilized for managing emergency disaster response operations is the:", listOf("Incident Command System (ICS)", "Maslow Hierarchy", "SWOT Analysis", "PNC Governance"), 0),
            Triple("Incident Commander (IC) in Incident Command System holds ultimate responsibility for:", listOf("Driving ambulance", "Overall management, strategy, and decision-making for the entire incident response", "Administering IV drugs", "Cooking food"), 1),
            Triple("Hospital Emergency Incident Command System (HEICS) adapts ICS to coordinate internal hospital emergency operations during mass casualty influx led by the:", listOf("Head Nurse", "Hospital Incident Commander (usually Medical Superintendent / Executive Director)", "Emergency Physician", "Janitorial lead"), 1),
            Triple("Decontamination in Chemical, Biological, Radiological, or Nuclear (CBRN) disaster response must be performed BEFORE patients enter hospital facility to prevent:", listOf("Water waste", "Secondary contamination of hospital staff, clean treatment areas, and unexposed patients", "Billing delays", "Patient panic"), 1),
            Triple("Primary initial step in field decontamination for chemical spill casualties is removing all patient clothing, which removes approximately what percentage of chemical contamination?", listOf("10%", "80% to 90% of chemical contamination", "30%", "100% complete"), 1),
            Triple("Personal Protective Equipment (PPE) Level A for CBRN disaster response provides the highest level of respiratory and skin protection consisting of:", listOf("Standard surgical mask and gown", "Totally encapsulating chemical-protective suit with self-contained breathing apparatus (SCBA)", "N95 mask and apron", "Gloves and face shield"), 1),
            Triple("Potassium Iodide (KI) tablets are distributed during radiological / nuclear disaster emergencies to protect which organ against absorption of radioactive iodine isotopes?", listOf("Liver", "Thyroid Gland (preventing radiation-induced thyroid cancer)", "Kidneys", "Lungs"), 1),
            Triple("Anthrax (Bacillus anthracis) aerosolized spore exposure during bioterrorism event is treated first-line with post-exposure prophylactic antibiotic therapy duration of 60 days using:", listOf("Amoxicillin", "Ciprofloxacin or Doxycycline", "Azithromycin", "Ceftriaxone"), 1),
            Triple("Smallpox (Variola virus) bioterrorism threat suspicion requires strict Airborne and Contact Precautions, immediate isolation, and ring vaccination using:", listOf("MMR vaccine", "Smallpox / Vaccinia Vaccine", "Varicella vaccine", "Polio drops"), 1),
            Triple("Botulinum Toxin (produced by Clostridium botulinum) causes lethal neuroparalytic illness presenting clinically with symmetrical descending flaccid paralysis and early:", listOf("High fever and hyperreflexia", "Cranial nerve palsies (diplopia, dysarthria, dysphagia, ptosis) without fever", "Severe diarrhea", "Generalized seizures"), 1),
            Triple("Mass Casualty Surge Capacity in hospital emergency management refers to the ability to rapidly expand hospital beds, personnel, equipment, and structural space to care for a sudden influx of:", listOf("Routine walk-in patients", "Critically injured casualties exceeding normal capacity", "Elective surgical patients", "Outpatient clinic visits"), 1),
            Triple("Psychological First Aid (PFA) principles provided to disaster survivors focus on promoting safety, calm, connectedness, self-efficacy, and:", listOf("Deep psychiatric analysis", "Hope and practical support for immediate basic needs", "Prescribing heavy sedatives", "Hypnosis"), 1),
            Triple("Post-Traumatic Stress Disorder (PTSD) long-term psychological intervention after mass disaster exposure includes evidence-based cognitive-behavioral therapy and:", listOf("Permanent isolation", "Eye Movement Desensitization and Reprocessing (EMDR)", "ECT therapy", "Hospital lockup"), 1),
            Triple("Complex Humanitarian Emergency (CHE) is defined as a multi-faceted humanitarian crisis combining armed conflict, mass population displacement, food insecurity, and:", listOf("High economic growth", "Breakdown of health systems and public infrastructure", "Urban technological expansion", "Zero mortality"), 1),
            Triple("Internally Displaced Persons (IDPs) differ from Refugees in international law because IDPs have been forced to flee their homes but have NOT crossed an:", listOf("Urban boundary", "Internationally recognized state border (remaining within home country)", "Ocean", "Hospital threshold"), 1),
            Triple("Refugee health management priority in temporary camp settings includes preventing explosive waterborne infectious disease outbreaks of:", listOf("Hypertension", "Cholera and Dysentery through clean water, sanitation, and Oral Cholera Vaccine", "Diabetes", "Asthma"), 1),
            Triple("Sphere Handbook minimum humanitarian standard for clean drinking water supply in disaster relief camps mandates providing at least how many liters per person per day?", listOf("2 Liters", "15 Liters per person per day (for drinking, cooking, and personal hygiene)", "50 Liters", "1 Liter"), 1),
            Triple("Sphere minimum humanitarian standard for basic toilet coverage in emergency disaster camps specifies a maximum ratio of how many people per latrine?", listOf("5 people per latrine", "20 people per latrine (separated by gender with safety locks/lights)", "100 people per latrine", "500 people"), 1),
            Triple("Cold Wave / Hypothermia emergency management in flood or earthquake displaced victims focuses on gradual rewarming, removing wet clothes, and applying:", listOf("Direct boiling hot water soak", "Warm dry blankets, insulation, and warm oral fluids if conscious", "Rubbing snow", "Alcohol massage"), 1),
            Triple("Heat Stroke (core body temperature > 40°C / 104°F with altered mental status) during extreme heat waves in KP requires rapid evaporative/immersion cooling targeting core temp drop to:", listOf("37°C within 30 minutes (stopping cooling at 38°C to prevent rebound hypothermia)", "30°C", "25°C", "42°C"), 0),
            Triple("Earthquake disaster injury management requires high clinical index of suspicion for Crush Syndrome caused by prolonged muscle compression resulting in rhabdomyolysis, hyperkalemia, and acute:", listOf("Liver failure", "Kidney Injury (Acute Tubular Necrosis due to myoglobinuria)", "Heart valve damage", "Stroke"), 1),
            Triple("First-line fluid resuscitation for Crush Injury victim prior to or immediately upon extrication from earthquake rubble is aggressive IV infusion of:", listOf("5% Dextrose in Water", "0.9% Normal Saline (bolus 1 to 1.5 L/hr to maintain high urine output > 200 mL/hr)", "Packed Red Blood Cells", "Hypertonic 3% Saline"), 1),
            Triple("Crush Injury victim with severe Rhabdomyolysis presenting with peaked T-waves on ECG requires urgent treatment for life-threatening:", listOf("Hypokalemia", "Hyperkalemia (using Calcium Gluconate, Insulin + Dextrose, Albuterol, and Dialysis)", "Hyponatremia", "Hypercalcemia"), 1),
            Triple("Flood disaster public health disease surveillance primary focus during post-flood standing water phase includes monitoring for Leptospirosis, Vector-borne diseases, and:", listOf("Cardiovascular diseases", "Waterborne Gastroenteritis (Diarrhea, Cholera, Typhoid, Hepatitis A/E)", "Lung cancer", "Osteoporosis"), 1),
            Triple("Leptospirosis infection contracted during wading through flood water contaminated with rat urine enters human body through:", listOf("Inhalation", "Skin abrasions, mucous membranes, or swallowed water", "Insect bites", "Intact nails"), 1),
            Triple("Wildfire smoke inhalation emergency care mandates high-flow 100% Oxygen administration to treat suspected toxicity from Carbon Monoxide and:", listOf("Carbon Dioxide", "Hydrogen Cyanide gas (treated with Hydroxocobalamin / Cyanokit)", "Nitrogen", "Helium"), 1),
            Triple("Triage tag color BLACK (Expectant / Deceased) in mass casualty disasters is assigned to casualties who are dead or whose injuries are so catastrophic that survival is unlikely even with:", listOf("Basic ice pack", "Maximal advanced resuscitation care, allowing resources to focus on red-tagged survivors", "Bandages", "Rest"), 1),
            Triple("In mass casualty disaster response, Ethical principle of Utility replaces individual patient autonomy, mandating doing the greatest good for the:", listOf("Individual richest patient", "Largest number of potential survivors", "Hospital board", "First arriving patient"), 1),
            Triple("Disaster Nursing Education core competencies established by International Council of Nurses (ICN) cover Ethical Practice, Legal Practice, Critical Thinking, Preparedness, Assessment, Response, and:", listOf("Financial Audit", "Recovery and Community Communication", "Private Business", "Hospital Ownership"), 1),
            Triple("Crisis Standards of Care (CSC) legally authorized during catastrophic disasters allow healthcare systems to shift from standard individual-centered care to:", listOf("No care", "Population-based resource allocation strategies prioritizing salvageable lives", "Paid care only", "Private clinic referrals"), 1),
            Triple("National Disaster Management Authority (NDMA) Pakistan and Provincial Disaster Management Authority (PDMA KP) lead national and provincial disaster policy, coordination, and:", listOf("Private medical practice", "Disaster risk reduction, relief allocation, and emergency rehabilitation", "Export management", "School grading"), 1),
            Triple("District Disaster Management Authority (DDMA) headed by the Deputy Commissioner (DC) at district level coordinates local disaster response involving health departments, rescue 1122, and:", listOf("Private real estate", "District Headquarter (DHQ) Hospital and emergency services", "Bank managers", "Foreign embassies"), 1),
            Triple("Rescue 1122 Emergency Service in Khyber Pakhtunkhwa provides pre-hospital emergency medical care, fire fighting, urban search and rescue, and water rescue across all districts of:", listOf("Federal territory only", "Khyber Pakhtunkhwa province", "Sindh", "Balochistan"), 1),
            Triple("Hospital Disaster Plan must be tested through full-scale functional simulation drills at least how often to maintain operational readiness?", listOf("Once every 10 years", "At least Annually (1 to 2 times per year)", "Never", "Every month"), 1)
        )
        addSubjectQs(8, "Professional Elective / Disaster Management", "KMU DIS-684 / Veenema Disaster Nursing & Emergency Preparedness", dis)

        // Add 100 extra questions for EACH subject in Semester 8 (400 extra questions)
        questions.addAll(KpSemester8PlusQuestionBank.getQuestions(idCounter))

        return questions
    }
